const relevantCategories = [
  'Tecnología', 'Inteligencia artificial', 'Economía',
  'Empresas', 'Transformación digital', 'i+d+i',
  'Grandes tecnológicas', 'Finanzas', 'Internet',
  'Innovación', 'Startups', 'Negocios', 'Ciencia',
  'Privacidad internet', 'Redes sociales', 'Ciberseguridad'
];

return items.filter(item => {
  const categories = item.json.categories || [];
  return categories.some(cat => relevantCategories.includes(cat));
});

const text = items[0].json.content[0].text;

// Limpiar bloques de markdown si los hay
const clean = text
  .replace(/```json\n?/g, '')
  .replace(/```\n?/g, '')
  .trim();

// Parsear el JSON
const parsed = JSON.parse(clean);

return [{ json: parsed }];

